// POSIX Dynamic Loading (Run-time linking via the Loader)

// Define the function signature expected from the shared library
typedef int (*calc_func)(int, int);

// 1. Open the shared library (.so)
void* lib_handle = dlopen("libgeometry.so", RTLD_LAZY | RTLD_GLOBAL);

if (!lib_handle) {
    // Handle error: Library not found or inaccessible
    return;
}

// 2. Resolve the symbol (find the function entry point)
calc_func area_ptr = (calc_func)dlsym(lib_handle, "calculate_area");

const char* error = dlerror();
if (error != NULL) {
    // Handle error: Function not found in library
    dlclose(lib_handle);
    return;
}

// 3. Use the loaded function
int result = area_ptr(10, 5);

// 4. Close the library handle
dlclose(lib_handle);

// Note: Requires compiling with -ldl
// ----------------------------------------------------------------
// Windows equivalent uses LoadLibrary/GetProcAddress/FreeLibrary
// ----------------------------------------------------------------
